function parseUser(value) {
  if (!value || typeof value !== "object" || !Number.isInteger(value.id)) {
    throw new TypeError("invalid user");
  }
  return { id: value.id };
}
console.log(parseUser({ id: 0 }));

function mount(button, output) {
  const onClick = () => { output.textContent = "Saved"; };
  button.addEventListener("click", onClick);
  return () => button.removeEventListener("click", onClick);
}

function reduce(state, action) {
  if (action.type === "start") return { status: "loading", data: null };
  if (action.type === "success" && state.status === "loading") {
    return { status: "ready", data: action.data };
  }
  return state;
}

function deferred() {
  let resolve, reject;
  const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
  return { promise, resolve, reject };
}
const pending = deferred();
pending.resolve(7);
pending.promise.then(console.log);

